Promise.resolve(1).then((v) => {
  console.log('then', v);
});
console.log('sync');
// logs: sync → then

queueMicrotask(() => console.log('q'));
Promise.resolve().then(() => console.log('p'));
// order is insertion order on the microtask queue

setTimeout(() => console.log('timeout'), 0);
Promise.resolve().then(() => console.log('then'));
// logs: then → timeout

function boom(n) {
  if (n <= 0) return;
  Promise.resolve().then(() => boom(n - 1));
}
boom(1000); // many microtasks before any timeout
